UPDATE tianquan_oauth.oauth_resource
SET display_name = #{po.displayName},
    rbac_application_code = #{po.rbacApplicationCode},
    entry_permission_code = #{po.entryPermissionCode},
    status = #{po.status},
    admission_ticket_ttl_seconds = #{po.admissionTicketTtlSeconds},
    version = #{po.version},
    update_user_id = #{po.updateUserId},
    update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId}
  AND id = #{po.id}
  AND resource_server_id = #{po.resourceServerId}
  AND resource_uri = #{po.resourceUri}
  AND biz_code = #{po.bizCode}
  AND app_code = #{po.appCode}
  AND environment = #{po.environment}
  AND management_client_id = #{po.managementClientId}
  AND management_client_pk = #{po.managementClientPk}
  AND version = #{expectedVersion}
  AND deleted_at IS NULL
